src/lib.rs
```rust
use std::{
    any::Any,
    collections::{HashMap, VecDeque},
    fmt,
    sync::{Arc, Weak},
    time::{Duration, Instant},
};

use tokio::{sync::Mutex, task::JoinHandle};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EvictReason {
    Expired,
    Lru,
    Memory,
}

impl fmt::Display for EvictReason {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            EvictReason::Expired => write!(f, "expired"),
            EvictReason::Lru => write!(f, "lru"),
            EvictReason::Memory => write!(f, "memory"),
        }
    }
}

pub type OnEvict<V> = Arc<dyn Fn(String, EvictReason) + Send + Sync>;

#[derive(Clone)]
pub struct CacheConfig {
    pub max_entries: usize,
    /// milliseconds
    pub default_ttl_ms: u64,
    pub max_memory_bytes: usize,
    /// milliseconds
    pub eviction_check_interval_ms: u64,
    pub on_evict: Option<OnEvict<()>>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1000,
            default_ttl_ms: 60_000,
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval_ms: 5_000,
            on_evict: None,
        }
    }
}

#[derive(Debug)]
struct CacheEntry<V> {
    value: Arc<V>,
    expires_at: Instant,
    size: usize,
    last_accessed: Instant,
    access_count: u64,
}

struct Inner<V> {
    entries: HashMap<String, CacheEntry<V>>,
    access_order: VecDeque<String>, // front = most-recent
    current_memory: usize,
    hits: u64,
    misses: u64,
    evictions: u64,
    expirations: u64,
    // weak refs upcasted to trait object (if V: Any + Send + Sync)
    weak_refs: HashMap<String, Weak<dyn Any + Send + Sync>>,
}

/// Stats snapshot
#[derive(Debug, Clone)]
pub struct CacheStats {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
    pub size: usize,
    pub memory: usize,
}

/// LRU Cache with TTL, weak refs, async eviction loop.
/// V must be 'static + Send + Sync so we can store Arc<dyn Any + Send + Sync> weak refs.
pub struct LruCache<V>
where
    V: Any + Send + Sync + 'static,
{
    inner: Mutex<Inner<V>>,
    config: CacheConfig,
    eviction_task: Mutex<Option<JoinHandle<()>>>,
}

impl<V> LruCache<V>
where
    V: Any + Send + Sync + 'static,
{
    pub fn new(config: Option<CacheConfig>) -> Self {
        let cfg = config.unwrap_or_default();
        let inner = Inner {
            entries: HashMap::new(),
            access_order: VecDeque::new(),
            current_memory: 0,
            hits: 0,
            misses: 0,
            evictions: 0,
            expirations: 0,
            weak_refs: HashMap::new(),
        };
        Self {
            inner: Mutex::new(inner),
            config: cfg,
            eviction_task: Mutex::new(None),
        }
    }

    /// Get value by key. Returns an Arc<V> to the stored value if present and not expired.
    /// Updates access info (last_accessed, access_count, moves to front).
    pub async fn get(&self, key: &str) -> Option<Arc<V>> {
        let now = Instant::now();
        let mut inner = self.inner.lock().await;
        match inner.entries.get_mut(key) {
            None => {
                inner.misses += 1;
                None
            }
            Some(entry) => {
                if now > entry.expires_at {
                    // expired
                    let key_owner = key.to_string();
                    // remove
                    let removed = inner.entries.remove(key);
                    if let Some(e) = removed {
                        inner.current_memory = inner.current_memory.saturating_sub(e.size);
                    }
                    inner.access_order.retain(|k| k != key);
                    inner.weak_refs.remove(key);
                    inner.expirations += 1;
                    inner.misses += 1;
                    drop(inner);
                    if let Some(cb) = &self.config.on_evict {
                        cb(key_owner, EvictReason::Expired);
                    }
                    None
                } else {
                    entry.last_accessed = Instant::now();
                    entry.access_count = entry.access_count.saturating_add(1);
                    // move to front
                    inner.access_order.retain(|k| k != key);
                    inner.access_order.push_front(key.to_string());
                    inner.hits += 1;
                    // return a clone of the Arc<V> (cheap)
                    Some(entry.value.clone())
                }
            }
        }
    }

    /// Put a value into the cache. ttl_ms and size are optional (ttl overrides default).
    pub async fn put(
        &self,
        key: String,
        value: V,
        ttl_ms: Option<u64>,
        size: Option<usize>,
    ) {
        let size_val = size.unwrap_or_else(|| self.estimate_size(&value));
        let ttl = Duration::from_millis(ttl_ms.unwrap_or(self.config.default_ttl_ms));
        let arc_value = Arc::new(value);

        // we will gather evictions to notify after releasing the lock
        let mut to_notify: Vec<(String, EvictReason)> = Vec::new();

        let mut inner = self.inner.lock().await;

        // If existing, remove old size and weak ref
        if inner.entries.contains_key(&key) {
            if let Some(old) = inner.entries.remove(&key) {
                inner.current_memory = inner.current_memory.saturating_sub(old.size);
            }
            inner.access_order.retain(|k| k != &key);
            inner.weak_refs.remove(&key);
        }

        // Evict by memory until it fits
        while inner.current_memory + size_val > self.config.max_memory_bytes
            && !inner.access_order.is_empty()
        {
            if let Some(old_key) = inner.access_order.pop_back() {
                if let Some(e) = inner.entries.remove(&old_key) {
                    inner.current_memory = inner.current_memory.saturating_sub(e.size);
                    inner.evictions = inner.evictions.saturating_add(1);
                    inner.weak_refs.remove(&old_key);
                    to_notify.push((old_key, EvictReason::Memory));
                }
            } else {
                break;
            }
        }

        // Evict by entry count (LRU) if necessary
        while inner.entries.len() >= self.config.max_entries && !inner.access_order.is_empty() {
            if let Some(old_key) = inner.access_order.pop_back() {
                if let Some(e) = inner.entries.remove(&old_key) {
                    inner.current_memory = inner.current_memory.saturating_sub(e.size);
                    inner.evictions = inner.evictions.saturating_add(1);
                    inner.weak_refs.remove(&old_key);
                    to_notify.push((old_key, EvictReason::Lru));
                }
            } else {
                break;
            }
        }

        // Insert new entry
        let now = Instant::now();
        let entry = CacheEntry {
            value: arc_value.clone(),
            expires_at: now + ttl,
            size: size_val,
            last_accessed: now,
            access_count: 0,
        };
        inner.entries.insert(key.clone(), entry);
        inner.current_memory = inner.current_memory.saturating_add(size_val);
        inner.access_order.retain(|k| k != &key);
        inner.access_order.push_front(key.clone());

        // Store weak ref (upcast Arc<V> to Arc<dyn Any + Send + Sync> and downgrade)
        let arc_any: Arc<dyn Any + Send + Sync> = arc_value.clone();
        let weak = Arc::downgrade(&arc_any);
        inner.weak_refs.insert(key.clone(), weak);

        drop(inner);

        if let Some(cb) = &self.config.on_evict {
            for (k, r) in to_notify {
                cb(k, r);
            }
        }
    }

    /// Delete a key, optionally providing a reason. Returns true if existed.
    pub async fn delete(&self, key: &str, reason: EvictReason) -> bool {
        let mut inner = self.inner.lock().await;
        if let Some(e) = inner.entries.remove(key) {
            inner.current_memory = inner.current_memory.saturating_sub(e.size);
            inner.access_order.retain(|k| k != key);
            inner.weak_refs.remove(key);
            if reason == EvictReason::Expired {
                inner.expirations = inner.expirations.saturating_add(1);
            } else {
                inner.evictions = inner.evictions.saturating_add(1);
            }
            let key_owned = key.to_string();
            drop(inner);
            if let Some(cb) = &self.config.on_evict {
                cb(key_owned, reason);
            }
            return true;
        }
        false
    }

    /// True if key exists and not expired. If expired, removes it and returns false.
    pub async fn has(&self, key: &str) -> bool {
        let now = Instant::now();
        let mut inner = self.inner.lock().await;
        if let Some(entry) = inner.entries.get(key) {
            if now > entry.expires_at {
                let key_owned = key.to_string();
                if let Some(e) = inner.entries.remove(key) {
                    inner.current_memory = inner.current_memory.saturating_sub(e.size);
                }
                inner.access_order.retain(|k| k != key);
                inner.weak_refs.remove(key);
                inner.expirations = inner.expirations.saturating_add(1);
                drop(inner);
                if let Some(cb) = &self.config.on_evict {
                    cb(key_owned, EvictReason::Expired);
                }
                return false;
            }
            true
        } else {
            false
        }
    }

    pub async fn size(&self) -> usize {
        let inner = self.inner.lock().await;
        inner.entries.len()
    }

    pub async fn memory_usage(&self) -> usize {
        let inner = self.inner.lock().await;
        inner.current_memory
    }

    pub async fn get_stats(&self) -> CacheStats {
        let inner = self.inner.lock().await;
        CacheStats {
            hits: inner.hits,
            misses: inner.misses,
            evictions: inner.evictions,
            expirations: inner.expirations,
            size: inner.entries.len(),
            memory: inner.current_memory,
        }
    }

    /// Clear all entries. Calls on_evict with Lru for each key (mirror TS behavior).
    pub async fn clear(&self) {
        let keys: Vec<String> = {
            let inner = self.inner.lock().await;
            inner.entries.keys().cloned().collect()
        };
        for k in keys {
            // use delete so stats and callbacks are consistent
            let _ = self.delete(&k, EvictReason::Lru).await;
        }
    }

    /// Start a background eviction loop. The cache instance must be Arc'd and you should call
    /// `cache.start_eviction_loop().await` on an Arc<LruCache<_>>.
    pub async fn start_eviction_loop(self: &Arc<Self>) {
        let mut guard = self.eviction_task.lock().await;
        if guard.is_some() {
            // already running
            return;
        }
        let self_cloned = Arc::clone(self);
        let interval_ms = self.config.eviction_check_interval_ms;
        let handle = tokio::spawn(async move {
            let mut interval = tokio::time::interval(Duration::from_millis(interval_ms));
            loop {
                interval.tick().await;
                self_cloned.evict_expired().await;
            }
        });
        *guard = Some(handle);
    }

    /// Stop the background eviction loop (if any).
    pub async fn stop_eviction_loop(&self) {
        let mut guard = self.eviction_task.lock().await;
        if let Some(handle) = guard.take() {
            handle.abort();
        }
    }

    /// Run one pass of expiration and weak-ref cleanup.
    pub async fn evict_expired(&self) {
        let mut to_notify: Vec<(String, EvictReason)> = Vec::new();
        let mut inner = self.inner.lock().await;
        let now = Instant::now();

        // find expired keys first
        let expired: Vec<String> = inner
            .entries
            .iter()
            .filter_map(|(k, e)| if now > e.expires_at { Some(k.clone()) } else { None })
            .collect();

        for k in expired.iter() {
            if let Some(e) = inner.entries.remove(k) {
                inner.current_memory = inner.current_memory.saturating_sub(e.size);
                inner.access_order.retain(|x| x != k);
                inner.weak_refs.remove(k);
                inner.expirations = inner.expirations.saturating_add(1);
                to_notify.push((k.clone(), EvictReason::Expired));
            }
        }

        // Clean up dead weak refs (and evict corresponding entries)
        let dead_keys: Vec<String> = inner
            .weak_refs
            .iter()
            .filter_map(|(k, w)| {
                if w.upgrade().is_none() && inner.entries.contains_key(k) {
                    Some(k.clone())
                } else {
                    None
                }
            })
            .collect();

        for k in dead_keys.iter() {
            if let Some(e) = inner.entries.remove(k) {
                inner.current_memory = inner.current_memory.saturating_sub(e.size);
                inner.access_order.retain(|x| x != k);
                inner.weak_refs.remove(k);
                inner.evictions = inner.evictions.saturating_add(1);
                to_notify.push((k.clone(), EvictReason::Memory));
            }
        }

        drop(inner);

        if let Some(cb) = &self.config.on_evict {
            for (k, r) in to_notify {
                cb(k, r);
            }
        }
    }

    /// Return keys in access order (most-recent first).
    pub async fn keys(&self) -> Vec<String> {
        let inner = self.inner.lock().await;
        inner.access_order.iter().cloned().collect()
    }

    /// Return stored values in access order (most-recent first).
    pub async fn values(&self) -> Vec<Arc<V>> {
        let inner = self.inner.lock().await;
        inner
            .access_order
            .iter()
            .filter_map(|k| inner.entries.get(k).map(|e| e.value.clone()))
            .collect()
    }

    /// Estimate size (in bytes) of a value. Implemented for common primitives; default 0.
    fn estimate_size(&self, value: &V) -> usize {
        let any = value as &dyn Any;
        if let Some(s) = any.downcast_ref::<String>() {
            s.len() * 2
        } else if any.downcast_ref::<i8>().is_some()
            || any.downcast_ref::<i16>().is_some()
            || any.downcast_ref::<i32>().is_some()
            || any.downcast_ref::<i64>().is_some()
            || any.downcast_ref::<u8>().is_some()
            || any.downcast_ref::<u16>().is_some()
            || any.downcast_ref::<u32>().is_some()
            || any.downcast_ref::<u64>().is_some()
            || any.downcast_ref::<f32>().is_some()
            || any.downcast_ref::<f64>().is_some()
        {
            8
        } else if any.downcast_ref::<bool>().is_some() {
            4
        } else {
            // fallback: unknown
            0
        }
    }
}
