src/main.rs
```rust
use std::sync::Arc;

use lru_cache::{CacheConfig, EvictReason, LruCache};

#[cfg(test)]
mod tests {
    use super::*;
    use tokio::time::{sleep, Duration};

    #[tokio::test]
    async fn run_tests() {
        // Basic configuration: maxEntries=3, defaultTtlMs=100
        let mut cfg = CacheConfig::default();
        cfg.max_entries = 3;
        cfg.default_ttl_ms = 100;
        let cache: Arc<LruCache<String>> = Arc::new(LruCache::new(Some(cfg)));

        // Basic get/put
        cache
            .put("a".to_string(), "hello".to_string(), None, None)
            .await;
        let v = cache.get("a").await;
        assert!(
            v.as_ref().map(|arc| &**arc == "hello").unwrap_or(false),
            "basic get"
        );
        assert_eq!(cache.size().await, 1, "size after put");

        // LRU eviction
        cache
            .put("b".to_string(), "world".to_string(), None, None)
            .await;
        cache
            .put("c".to_string(), "foo".to_string(), None, None)
            .await;
        cache
            .put("d".to_string(), "bar".to_string(), None, None)
            .await; // should evict 'a'
        assert!(!cache.has("a").await, "lru eviction");
        assert!(cache.has("d").await, "newest kept");

        // TTL expiration
        cache.clear().await;
        cache
            .put("x".to_string(), "temp".to_string(), Some(50), None)
            .await;
        sleep(Duration::from_millis(80)).await;
        assert_eq!(cache.get("x").await, None, "ttl expired");

        // Access order
        cache.clear().await;
        cache
            .put("1".to_string(), "one".to_string(), None, None)
            .await;
        cache
            .put("2".to_string(), "two".to_string(), None, None)
            .await;
        cache
            .put("3".to_string(), "three".to_string(), None, None)
            .await;
        // access '1', making '2' the LRU
        let _ = cache.get("1").await;
        cache
            .put("4".to_string(), "four".to_string(), None, None)
            .await; // should evict '2'
        assert!(!cache.has("2").await, "access order eviction");
        assert!(cache.has("1").await, "accessed item kept");

        // Stats
        let stats = cache.get_stats().await;
        assert!(stats.hits > 0, "has hits");
        assert!(stats.misses > 0, "has misses");

        // Eviction loop
        let mut cfg2 = CacheConfig::default();
        cfg2.max_entries = 10;
        cfg2.default_ttl_ms = 50;
        cfg2.eviction_check_interval_ms = 30;
        let cache2: Arc<LruCache<String>> = Arc::new(LruCache::new(Some(cfg2)));
        cache2
            .put("e1".to_string(), "val1".to_string(), None, None)
            .await;
        // start eviction loop (background)
        cache2.start_eviction_loop().await;
        sleep(Duration::from_millis(150)).await;
        assert!(
            !cache2.has("e1").await,
            "eviction loop cleared expired"
        );
        cache2.stop_eviction_loop().await;

        println!("All tests passed");
    }
}

fn main() {
    // Nothing to run here; run tests with `cargo test`.
}
```

---

How to run
1. Save the files in a new Rust project (cargo new lru_cache)
2. Replace Cargo.toml, src/lib.rs, src/main.rs with the snippets above
3. Run cargo test

This implementation is fully safe (no unsafe blocks), uses Tokio for the async eviction loop, and mirrors the TypeScript cache behavior exercised in the provided tests.
